package fr.descentecanyon.app.data.local.catalog

import android.app.Application
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import java.io.File
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.test.runTest
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/**
 * Opens the catalog generated by `scripts/app/generate_prepackaged_room_db.py` with Room: Room
 * refuses a pre-packaged database whose schema differs from [CatalogDatabase], so this guards the
 * generator against drifting from the entities.
 */
@RunWith(RobolectricTestRunner::class)
@Config(application = Application::class)
class CatalogAssetTest {

    private val generatedCatalog = File("build/generated/catalog-db/catalog.db")
    private var database: CatalogDatabase? = null

    @After
    fun tearDown() {
        database?.close()
        ApplicationProvider.getApplicationContext<android.content.Context>().deleteDatabase(TEST_DATABASE_NAME)
    }

    @Test
    fun `the generated catalog matches the Room schema and holds the whole dataset`() = runTest {
        assumeTrue("Catalog not generated (run the Gradle build)", generatedCatalog.exists())
        val catalog = Room.databaseBuilder(
            ApplicationProvider.getApplicationContext<android.content.Context>(),
            CatalogDatabase::class.java,
            TEST_DATABASE_NAME,
        )
            .createFromFile(generatedCatalog)
            .allowMainThreadQueries()
            .build()
            .also { database = it }

        val canyonCount = catalog.canyonDao().count()
        assertTrue("Unexpectedly small catalog: $canyonCount", canyonCount > 1_000)
        assertEquals(canyonCount, catalog.searchIndexDao().count())
        assertEquals(canyonCount, catalog.searchIndexDao().observeAll().first().size)
        assertNotNull(catalog.canyonDao().getById(2186))
    }

    private companion object {
        const val TEST_DATABASE_NAME = "catalog-asset-test.db"
    }
}
